   esql("FROM kibana_sample_data_logs | STATS count = COUNT() BY response = response.keyword","Requests by response code",24,6,24,"bar","response","count")]
print(json.dumps({"title":"EFF-1685382b Web logs overview","time_range":{"from":"now-7d","to":"now"},"panels":p}))
EOF
curl -s -XPOST -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json" "$KIBANA_URL/api/dashboards" -d @$S/d.json | head -c 1500

